function f = HS20_f(x)
f = (1 - x(1)).^2 + 100*(-x(1).^2 + x(2)).^2;
end

function g = HS20_g(x)
g = zeros(2, 1);
g(1) = -400*x(1).*(-x(1).^2 + x(2)) + 2*x(1) - 2;
g(2) = -200*x(1).^2 + 200*x(2);
end

function c = HS20_c(x)
c = zeros(3, 1);
c(1) = x(1) + x(2).^2;
c(2) = x(1).^2 + x(2);
c(3) = x(1).^2 + x(2).^2 - 1;
end

function J = HS20_J(x)
J = zeros(3, 2);
J(1, 1) = 1;
J(1, 2) = 2*x(2);
J(2, 1) = 2*x(1);
J(2, 2) = 1;
J(3, 1) = 2*x(1);
J(3, 2) = 2*x(2);
end
